"use strict";(globalThis.webpackChunkdocusaurus_resource=globalThis.webpackChunkdocusaurus_resource||[]).push([[6575],{26202:e=>{e.exports=JSON.parse('{"tag":{"label":"aria","permalink":"/accessibility-hub/docs/tags/aria","allTagsPath":"/accessibility-hub/docs/tags","count":6,"items":[{"id":"hot-topics/accessibility-testing","title":"Accessibility Testing","description":"Accessibility Testing covers the tools, methods, and best practices for evaluating digital content for accessibility. This page will be expanded and curated with more detailed guidance and resources in the future.","permalink":"/accessibility-hub/docs/hot-topics/accessibility-testing"},{"id":"for-developers/accessible-api-design-guide","title":"Accessible API Design for Developers","description":"Accessibility in software is often associated with user interfaces, but it is equally important in API and schema design. Accessible APIs improve usability for developers using assistive technologies, enhance code readability, and support better tooling integration. This guide outlines key strategies Java developers can adopt to make their APIs more inclusive.","permalink":"/accessibility-hub/docs/for-developers/accessible-api-design-guide"},{"id":"for-developers/accessible-web-dev-checklist","title":"Accessible Web Development Checklist","description":"A comprehensive checklist based on WCAG 2.1 Level AA and best practices from W3C, WebAIM, and Section508.gov.","permalink":"/accessibility-hub/docs/for-developers/accessible-web-dev-checklist"},{"id":"hot-topics/aria-roles","title":"ARIA Roles","description":"ARIA Roles define the purpose of elements in web content for assistive technologies. More curated content and examples will be added to this page in the future.","permalink":"/accessibility-hub/docs/hot-topics/aria-roles"},{"id":"community-contributions/contributing","title":"Contributing to the Accessibility Hub","description":"Thank you for your interest in contributing to our Accessibility Hub!","permalink":"/accessibility-hub/docs/community-contributions/contributing"},{"id":"for-developers/how-to-contribute","title":"How to contribute","description":"Developers play a crucial role in making the world more accessible by designing and building digital experiences that are inclusive of people with disabilities. Here are several impactful ways developers can contribute:","permalink":"/accessibility-hub/docs/for-developers/how-to-contribute"}],"unlisted":false}}')}}]);